package com.Alcura.Customer.Controller.MedicineModelController;import com.Alcura.Customer.DTO.MedicineClassificationResult;import com.Alcura.Customer.DTO.DrugInfo;import com.fasterxml.jackson.core.json.JsonReadFeature;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RequestParam;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.util.Base64;import java.util.Map;@Controller@RequestMapping("/Customer")public class MedicineWebController{    private final MedicineClassifierController classifierController;    public MedicineWebController(MedicineClassifierController medicineClassifierController)    {        this.classifierController = medicineClassifierController;    }    @PostMapping("/MedicineClassifier")    public String classify(@RequestParam("file")MultipartFile file,                           RedirectAttributes redirectAttributes)    {        try        {            ResponseEntity<String> response = classifierController.classifyMedicine(file);            if(response.getStatusCode() == HttpStatus.OK)            {                ObjectMapper mapper = new ObjectMapper();                mapper.enable(JsonReadFeature.ALLOW_NON_NUMERIC_NUMBERS.mappedFeature());                Map<String,Object> responeMap = mapper.readValue(response.getBody(), Map.class);                Map<String, Object> drugInfoMap = (Map<String,Object>) responeMap.get("drug_info");                DrugInfo drugInfo = mapper.convertValue(drugInfoMap,DrugInfo.class);                MedicineClassificationResult result = new MedicineClassificationResult(                        (String) responeMap.get("predicted_class"),                        (Double) responeMap.get("confidence"),                        drugInfo                );                redirectAttributes.addFlashAttribute("result", result);                redirectAttributes.addFlashAttribute("status", "");                if (!file.isEmpty()) {                    String imageBase64 = Base64.getEncoder().encodeToString(file.getBytes());                    redirectAttributes.addFlashAttribute("imagePreview",                            "data:image/jpeg;base64," + imageBase64);                }            } else {                redirectAttributes.addFlashAttribute("status",                        "Classification failed: " + response.getBody());                }            }        catch (Exception e)        {            redirectAttributes.addFlashAttribute("status",                    "Error: " + e.getMessage());        }        return "redirect:/Customer/MedicineClassifier";    }}